create function public.cineo_storage_totals() returns jsonb language sql stable security invoker set search_path='' as $$select coalesce(jsonb_agg(x),'[]') from (select bucket_id,count(*) as files,coalesce(sum((metadata->>'size')::bigint),0) as bytes from storage.objects where bucket_id like 'cineo-%' group by bucket_id)x$$;
create function public.cineo_retention_stats(sid bigint) returns jsonb language sql stable security invoker set search_path='' as $$select jsonb_build_object('buckets',(select jsonb_agg(x order by x.bucket) from (select b as bucket,count(distinct r.user_id) as viewers from generate_series(0,9)b left join public.cineo_retention r on r.bucket=b and r.episode_id in (select id from public.cineo_episodes where show_id=sid) group by b)x),'episodes',(select coalesce(jsonb_agg(x),'[]') from (select e.id,e.title,count(distinct p.user_id) as viewers,coalesce(sum(least(p.position_ms,p.duration_ms)),0) as watched_ms,count(*) filter(where p.completed) as completions from public.cineo_episodes e left join public.cineo_progress p on p.episode_id=e.id where e.show_id=sid group by e.id)x))$$;
revoke all on function public.cineo_storage_totals(),public.cineo_retention_stats(bigint) from public,anon,authenticated;
grant execute on function public.cineo_storage_totals(),public.cineo_retention_stats(bigint) to service_role;
